python3 - <<'PYEOF' > $TMPDIR/pattern1_drv.txt
import re, os
free_re = re.compile(r'\b(kfree_skb|consume_skb|dev_kfree_skb_any|dev_kfree_skb_irq|napi_consume_skb|skb_unref|__kfree_skb)\s*\(')
save_re = re.compile(r'(\w+)\s*=\s*skb->data\b|\b(\w+)\s*=\s*skb_header_pointer\s*\(|(\w+)\s*=\s*skb_(network|transport|mac)_header\s*\(')
files = set()
for dirpath, dirnames, filenames in os.walk("./drivers/net"):
    for fn in filenames:
        if fn.endswith(".c"):
            files.add(os.path.join(dirpath, fn))
for path in sorted(files):
    try:
        src = open(path, errors='replace').read().splitlines()
    except OSError:
        continue
    for i, line in enumerate(src):
        if free_re.search(line):
            window_b = src[max(0,i-30):i]
            m = save_re.search(' '.join(window_b))
            if not m:
                continue
            var = m.group(1) or m.group(2) or m.group(3)
            window_a = src[i+1:min(len(src),i+31)]
            for l2 in window_a:
                if re.search(r'\b'+re.escape(var)+r'\b', l2):
                    print(f"{path}:{i+1}:{line.strip()[:90]} | var={var} | use: {l2.strip()[:80]}")
                    break
PYEOF
wc -l < $TMPDIR/pattern1_drv.txt; cat $TMPDIR/pattern1_drv.txt | head -50

